import React from 'react';
import { HistoryDataPoint } from '../types';

interface TrendChartProps {
  data: HistoryDataPoint[];
}

export const TrendChart: React.FC<TrendChartProps> = ({ data }) => {
  if (data.length === 0) {
    return (
      <div className="chart-container">
        <div className="chart-empty">
          <p>📊 暂无数据，开始对话后将显示心理变化趋势</p>
        </div>
      </div>
    );
  }

  const padding = 40;
  const width = 600;
  const height = 250;
  const chartWidth = width - padding * 2;
  const chartHeight = height - padding * 2;

  const maxValue = 100;
  const minValue = 0;

  const getX = (index: number) => padding + (index / (data.length - 1)) * chartWidth;
  const getY = (value: number) => padding + chartHeight - ((value - minValue) / (maxValue - minValue)) * chartHeight;

  const stressPath = data
    .map((point, i) => `${i === 0 ? 'M' : 'L'} ${getX(i)} ${getY(point.stressLevel)}`)
    .join(' ');

  const anxietyPath = data
    .map((point, i) => `${i === 0 ? 'M' : 'L'} ${getX(i)} ${getY(point.anxietyLevel)}`)
    .join(' ');

  const moodPath = data
    .map((point, i) => `${i === 0 ? 'M' : 'L'} ${getX(i)} ${getY(point.moodStability)}`)
    .join(' ');

  const stressArea = `${stressPath} L ${getX(data.length - 1)} ${height - padding} L ${padding} ${height - padding} Z`;
  const anxietyArea = `${anxietyPath} L ${getX(data.length - 1)} ${height - padding} L ${padding} ${height - padding} Z`;
  const moodArea = `${moodPath} L ${getX(data.length - 1)} ${height - padding} L ${padding} ${height - padding} Z`;

  const gridLines = [];
  for (let i = 0; i <= 4; i++) {
    const y = padding + (chartHeight / 4) * i;
    const value = maxValue - (maxValue / 4) * i;
    gridLines.push(
      <g key={i}>
        <line
          x1={padding}
          y1={y}
          x2={width - padding}
          y2={y}
          stroke="#e0e0e0"
          strokeDasharray="4"
        />
        <text x={padding - 10} y={y + 4} textAnchor="end" fill="#666" fontSize="12">
          {value}
        </text>
      </g>
    );
  }

  return (
    <div className="chart-container">
      <h3 className="chart-title">📈 心理变化趋势</h3>
      <svg width={width} height={height} className="trend-svg">
        <defs>
          <linearGradient id="stressGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="rgba(244, 67, 54, 0.3)" />
            <stop offset="100%" stopColor="rgba(244, 67, 54, 0.05)" />
          </linearGradient>
          <linearGradient id="anxietyGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="rgba(255, 152, 0, 0.3)" />
            <stop offset="100%" stopColor="rgba(255, 152, 0, 0.05)" />
          </linearGradient>
          <linearGradient id="moodGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="rgba(76, 175, 80, 0.3)" />
            <stop offset="100%" stopColor="rgba(76, 175, 80, 0.05)" />
          </linearGradient>
        </defs>

        {gridLines}

        <path d={stressArea} fill="url(#stressGradient)" />
        <path d={anxietyArea} fill="url(#anxietyGradient)" />
        <path d={moodArea} fill="url(#moodGradient)" />

        <path
          d={stressPath}
          fill="none"
          stroke="#F44336"
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d={anxietyPath}
          fill="none"
          stroke="#FF9800"
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d={moodPath}
          fill="none"
          stroke="#4CAF50"
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />

        {data.map((point, i) => (
          <React.Fragment key={i}>
            <circle cx={getX(i)} cy={getY(point.stressLevel)} r="4" fill="#F44336" />
            <circle cx={getX(i)} cy={getY(point.anxietyLevel)} r="4" fill="#FF9800" />
            <circle cx={getX(i)} cy={getY(point.moodStability)} r="4" fill="#4CAF50" />
          </React.Fragment>
        ))}

        <text x={width / 2} y={height - 10} textAnchor="middle" fill="#666" fontSize="12">
          时间 →
        </text>
      </svg>

      <div className="chart-legend">
        <div className="legend-item">
          <span className="legend-color" style={{ backgroundColor: '#F44336' }}></span>
          <span>压力值</span>
        </div>
        <div className="legend-item">
          <span className="legend-color" style={{ backgroundColor: '#FF9800' }}></span>
          <span>焦虑值</span>
        </div>
        <div className="legend-item">
          <span className="legend-color" style={{ backgroundColor: '#4CAF50' }}></span>
          <span>情绪平稳度</span>
        </div>
      </div>
    </div>
  );
};
